using Maestro.Quest.Creation;
using Maestro.Quest.Diagnostics;
using Newtonsoft.Json.Linq;
namespace Maestro.Quest.Programs
{
    public static class FlowWorkFacts
    {
        static bool Available(BehaviourCatalog.FactContext context)=>context.Editor&&context.Editor.GetComponentInParent<RuntimeDiagnostics>();
        static readonly string[] Features={RuntimeDiagnosticFacts.Feature};
        public static BehaviourCatalog.FactDefinition Budget()=>new("runtime.flowWorkBudget",ProgramDataType.Read(JObject.Parse(@"{""record"":{""reservations"":""number"",""units"":""number"",""reservationLimit"":""number"",""unitLimit"":""number"",""streamSegments"":""number"",""queryHits"":""number"",""scoopSamples"":""number"",""rainSamples"":""number""}}")),
            "Liquid transfer work budget","Process-wide liquid-work host registrations. Reservations retain their host meaning, including waiting rooms; units sum booked complete quantity-group member allowances. Independent quantity groups are admitted separately with their own moving-body dependencies. Shared read-only solids or roofs do not join groups. Discovery remains independently bounded per host, and all groups retain one atomic quantity publication and Undo episode. Empty receivers and missing cavities participate in their actual dependency closure. Waiting retains valid motion and inputs without catch-up; source, placement and ownership changes require fresh preparation. Scheduled holds contribute their retained velocity/spin to flow trajectory discovery. Consumed charges survive request removal and regrouping until the next opportunity; inspect runtime.simulationWorkLedger. Inspect runtime.flowGroupSchedule, runtime.flowGroup and runtime.flowGroupMember for actual group admission. Logical units bound potential work, not CPU time, frame rate, memory or PhysX cost. Reads never admit work, load geometry, start physics or publish quantities.",null,null,
            (context,args)=>Available(context)?ProgramValue.Literal(FlowWorkResources.ObserveBudget()):null,features:Features);
        public static BehaviourCatalog.FactDefinition Schedule()=>new("runtime.flowWorkSchedule",ProgramDataType.Read(JObject.Parse(@"{""record"":{""step"":""number"",""executions"":""number"",""executionLimit"":""number"",""queued"":""number"",""queueLimit"":""number"",""units"":""number"",""unitLimit"":""number""}}")),
            "Liquid simulation opportunities","Read the shared early fixed-step clock and host counts: executions counts hosts with any booked group; queued counts hosts with none. executionLimit remains 32, an upper bound on these hosts because the actual shared limit is 32 complete quantity groups; inspect runtime.flowGroupSchedule for that finer count. Booked allowances may be stale until refreshed and do not prove execution. Priority uses oldest unserved canonical member, then stable registration order, retained across regrouping and native view replacement. A finite unchanged complete group that fits receives a turn under continuing demand. Automatic work runs at most once per canonical member per opportunity, with no accumulated time debt. Reading cannot advance the clock or claim work.",null,null,
            (context,args)=>Available(context)?ProgramValue.Literal(FlowWorkResources.ObserveSchedule()):null,features:Features);
        public static BehaviourCatalog.FactDefinition Discovery()=>new("runtime.flowDiscoveryBudget",ProgramDataType.Read(JObject.Parse(@"{""record"":{""step"":""number"",""reservations"":""number"",""executions"":""number"",""units"":""number"",""unitLimit"":""number"",""objectLimit"":""number""}}")),
            "Liquid dependency discovery budget","Process-wide booked discovery allowances on the shared simulation clock. Liquid discovery is independently admitted before its collision/cavity capture, candidate queries and native input preparation. Native inputs may load while liquid execution waits. Discovery grants are selected first on the shared clock; dependent physics and liquid execution remain queued until the discovery prerequisite is ready, then receive both execution allowances together. A preparation wait preserves service age and does not refund already booked execution within its opportunity. Demand uses canonical object and vessel counts, including dormant objects and empty containers. A changed count or world owner invalidates readiness until refreshed. One fresh collision snapshot and one physical adjacency graph are reused only inside the synchronous discovery pass; later passes read current placements and broken-joint state. Physical connectivity traversal is linear in reached members and edges. objectLimit is the independent spatial-query capacity, not a saved-room or resident-object quota; the unit allowance can refuse a larger combination of object and vessel counts. Units conservatively cover bounded metadata/candidate/trajectory and connection-graph visits, not measured CPU time, geometry/proof internals, allocation, sorting, native loading, PhysX or device frame time. Reservations include waiting claims and executions count booked grants, which can be stale until refreshed; neither proves native readiness or completed discovery. Passive reads cannot admit work, capture geometry, load native objects, advance the clock or change quantities. Saved/native limits are unchanged. Execution is independently admitted per complete quantity group.",null,null,
            (context,args)=>Available(context)?ProgramValue.Literal(FlowWorkResources.ObserveDiscovery()):null,features:Features);
        public static BehaviourCatalog.FactDefinition Reservation()=>new("runtime.flowWorkReservation",ProgramDataType.Read(JObject.Parse(@"{""record"":{""reservationId"":""text"",""worldId"":""text"",""regionId"":""text"",""vessels"":""number"",""units"":""number"",""current"":""boolean""}}")),
            "Liquid transfer work request","Read one host registration by index. Indices may shift; reservationId is runtime-only. World/region identify the copied owner. units sums requested group demand, including conservative undiscovered placeholders. Current means at least one complete group is ready in this opportunity; it does not mean every group in the host can execute or any quantity has transferred. Inspect runtime.flowGroup for the complete-group readiness and costs. Group resizing cannot evict peers or refund consumed work. Canonical service identity survives native view retirement and regrouping. Paused, inactive or destroyed hosts release requests; explicit internal ticks can step a disabled automatic loop for desktop verification. Reads are detached and cannot resume transfers or physics.",
            CapabilitySchema.Object(new JObject{["index"]=CapabilitySchema.Number(0,FlowWorkResources.MaximumReservations-1,true)}),new JObject{["index"]=0},
            (context,args)=>!Available(context)?null:FlowWorkResources.Observe((int)args["index"]) is JObject value?ProgramValue.Literal(value):null,features:Features);
    }
}
